  foreach(var c in u.nightConfigs){c.scratching=Clip("UnderTheBedMonster/Scratching.mp3");c.emerging=c.exposed=c.breathing=c.retreating=c.safeToUncover=c.attacking=sentinel;c.scratchingDuration=.6f;c.emergingDuration=.8f;}
  foreach(var c in w.nightConfigs){c.quietKnock=c.aggressiveKnock=Clip("WindowMonster/KnockingWindow.mp3");c.opening=Clip("WindowMonster/OpenWindow.mp3");c.latchRattle=c.monsterBreathing=c.retreating=c.attacking=c.closing=sentinel;c.openingDuration=.8f;c.knockingDuration=5;c.emergingDuration=2;c.silentApproachDuration=.25f;c.silentEmergingDuration=.6f;c.minimumEmerging=.6f;c.retreatDuration=.4f;c.attackDuration=.5f;}
  d.SetEncountersEnabled(false);u.SetEncountersEnabled(false);w.SetEncountersEnabled(false);
  var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){bool more=false;object next=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception ex){report.error=ex.ToString();break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested){stack.Push(nested);continue;}yield return next;}
