  Check(p.nightExcursion.TryLeaveBed(),"normal get-out-of-bed interaction remains available");yield return Wait(()=>p.NightStanding&&!p.IsTransitioning);w.panel.closingAudioNormalizedTime=.8f;Check(w.panel.TryClose(),"manual closing starts normally");yield return new WaitForSeconds(.3f);Check(!w.panel.closingSource.isPlaying,"optional close/latch sound waits for configured animation point");yield return Wait(()=>w.panel.closingSource.isPlaying);sample=w.panel.closingSource.time;yield return new WaitForSeconds(.1f);Check(w.panel.closingSource.time>sample,"manual close audio triggers once instead of restarting each frame");yield return Wait(()=>!w.panel.IsAnimating);Check(!w.panel.IsWindowOpen&&w.DangerMultiplier==1,"manual closing still resets open-window danger");Check(p.nightExcursion.TryReturnToBed(),"normal return-to-bed interaction remains available");yield return Wait(()=>p.CanUseNightDefenses);yield return new WaitForSeconds(.1f);w.ResetEncounter();Check(w.ForceStartEncounter(),"window attack test starts");yield return Wait(()=>w.State==WindowMonsterState.Attack);Check(w.breathingSource.isPlaying&&w.breathingSource.clip==sentinel,"optional window attack reuses voice source once");yield return Wait(()=>p.State==BedroomPhase.NightLost);Check(WindowSources().Where(s=>s!=w.breathingSource).All(s=>!s.isPlaying)&&!w.panel.closingSource.isPlaying&&w.breathingSource.isPlaying,"loss cancels window loops and manual-close audio while preserving attack tail");yield return new WaitForSeconds(.7f);Check(!w.breathingSource.isPlaying,"window attack tail finishes naturally");p.RetryNight();w.SetEncountersEnabled(false);yield return null;p.night.nightDurationSeconds=.2f;p.night.BeginNight();yield return Wait(()=>p.State==BedroomPhase.NightWon);Check(DoorSources().Concat(UnderSources()).Concat(WindowSources()).All(s=>!s.isPlaying),"night victory leaves all monster audio stopped");Check(FindObjectsByType<Camera>().Count(c=>c.enabled)==1&&FindObjectsByType<AudioListener>().Count(c